(function ($) {
	'use strict';
	window.ShahiComponents = {
		init() {
			this.initCounters();
			this.initTooltips();
			this.initRippleEffect();
			this.initScrollAnimations();
			this.initNotifications();
		},
		initCounters() {
			$('.shahi-counter').each(function () {
				const $counter = $(this);
				const target = parseInt(
					$counter.data('target') || $counter.text()
				);
				const duration = parseInt($counter.data('duration') || 2000);
				let current = 0;
				const increment = target / (duration / 16);
				const updateCounter = function () {
					current += increment;
					if (current < target) {
						$counter.text(Math.floor(current).toLocaleString());
						requestAnimationFrame(updateCounter);
					} else {
						$counter.text(target.toLocaleString());
					}
				};
				var observer = new IntersectionObserver(function (entries) {
					if (entries[0].isIntersecting) {
						updateCounter();
						observer.disconnect();
					}
				});
				observer.observe($counter[0]);
			});
		},
		initTooltips() {
			$('[data-tooltip]').each(function () {
				const $element = $(this);
				const tooltipText = $element.data('tooltip');
				const position = $element.data('tooltip-position') || 'top';
				if (!$element.hasClass('shahi-tooltip')) {
					$element.addClass(
						'shahi-tooltip shahi-tooltip-' + position
					);
					const $tooltip = $(
						'<span class="shahi-tooltip-content"></span>'
					);
					$tooltip.text(tooltipText);
					$element.append($tooltip);
				}
			});
		},
		initRippleEffect() {
			$(document).on(
				'click',
				'.shahi-button,.shahi-ripple-container',
				function (e) {
					const $button = $(this);
					const $ripple = $('<span class="shahi-ripple"></span>');
					const rect = this.getBoundingClientRect();
					const size = Math.max(rect.width, rect.height);
					const x = e.clientX - rect.left - size / 2;
					const y = e.clientY - rect.top - size / 2;
					$ripple.css({ width: size, height: size, left: x, top: y });
					$button.append($ripple);
					setTimeout(function () {
						$ripple.remove();
					}, 600);
				}
			);
		},
		initScrollAnimations() {
			const observer = new IntersectionObserver(
				function (entries) {
					entries.forEach(function (entry) {
						if (entry.isIntersecting) {
							entry.target.classList.add('visible');
						}
					});
				},
				{ threshold: 0.1 }
			);
			$('.shahi-scroll-fade-in').each(function () {
				observer.observe(this);
			});
		},
		notifications: {
			container: null,
			init() {
				if (!this.container) {
					this.container = $(
						'<div class="shahi-notifications-container"></div>'
					);
					$('body').append(this.container);
				}
			},
			show(message, type, duration) {
				this.init();
				type = type || 'info';
				duration = duration || 5000;
				const icons = {
					success: 'dashicons-yes-alt',
					error: 'dashicons-dismiss',
					warning: 'dashicons-warning',
					info: 'dashicons-info',
				};
				const $notification = $(
					`<div class="shahi-notification shahi-notification-${type}shahi-notification-enter"><div class="shahi-notification-icon"><span class="dashicons ${icons[type]}"></span></div><div class="shahi-notification-content"><p class="shahi-notification-message">${message}</p></div><button class="shahi-notification-close"><span class="dashicons dashicons-no-alt"></span></button></div>`
				);
				this.container.append($notification);
				setTimeout(function () {
					$notification.addClass('shahi-notification-exit');
					setTimeout(function () {
						$notification.remove();
					}, 300);
				}, duration);
				$notification
					.find('.shahi-notification-close')
					.on('click', function () {
						$notification.addClass('shahi-notification-exit');
						setTimeout(function () {
							$notification.remove();
						}, 300);
					});
			},
			success(message, duration) {
				this.show(message, 'success', duration);
			},
			error(message, duration) {
				this.show(message, 'error', duration);
			},
			warning(message, duration) {
				this.show(message, 'warning', duration);
			},
			info(message, duration) {
				this.show(message, 'info', duration);
			},
		},
		initNotifications() {
			this.notifications.init();
		},
		animateProgress($progressBar, targetValue, duration) {
			duration = duration || 1000;
			let currentValue = 0;
			const increment = targetValue / (duration / 16);
			const updateProgress = function () {
				currentValue += increment;
				if (currentValue < targetValue) {
					$progressBar.css('width', currentValue + '%');
					requestAnimationFrame(updateProgress);
				} else {
					$progressBar.css('width', targetValue + '%');
				}
			};
			updateProgress();
		},
		initToggles() {
			$(document).on('change', '.shahi-toggle-input', function () {
				const $input = $(this);
				const $toggle = $input.closest('.shahi-toggle');
				if ($input.is(':checked')) {
					$toggle.addClass('shahi-toggle-active');
				} else {
					$toggle.removeClass('shahi-toggle-active');
				}
				$toggle.trigger('shahi:toggle', [$input.is(':checked')]);
			});
		},
		confetti($container, count) {
			count = count || 50;
			const colors = [
				'#60a5fa',
				'#93c5fd',
				'#10b981',
				'#f59e0b',
				'#ec4899',
				'#8b5cf6',
			];
			for (let i = 0; i < count; i++) {
				const $piece = $('<div class="shahi-confetti-piece"></div>');
				$piece.css({
					left: Math.random() * 100 + '%',
					background:
						colors[Math.floor(Math.random() * colors.length)],
					animationDelay: Math.random() * 2 + 's',
					animationDuration: Math.random() * 2 + 2 + 's',
				});
				$container.append($piece);
			}
			setTimeout(function () {
				$container.find('.shahi-confetti-piece').remove();
			}, 5000);
		},
		loading: {
			show(message) {
				message = message || 'Loading...';
				const $overlay = $(
					`<div class="shahi-loading-overlay"><div class="shahi-spinner"></div><div class="shahi-loading-text">${message}</div></div>`
				);
				$('body').append($overlay);
			},
			hide() {
				$('.shahi-loading-overlay').fadeOut(300, function () {
					$(this).remove();
				});
			},
		},
		createSkeletons($container, count) {
			count = count || 3;
			for (let i = 0; i < count; i++) {
				const $skeleton = $(
					`<div class="shahi-skeleton-item"><div class="shahi-skeleton shahi-skeleton-avatar"></div><div><div class="shahi-skeleton shahi-skeleton-title"></div><div class="shahi-skeleton shahi-skeleton-text"></div><div class="shahi-skeleton shahi-skeleton-text"></div></div></div>`
				);
				$container.append($skeleton);
			}
		},
		copyToClipboard(text, callback) {
			const $temp = $('<textarea>');
			$('body').append($temp);
			$temp.val(text).select();
			try {
				document.execCommand('copy');
				if (callback) callback(true);
				this.notifications.success('Copied to clipboard!');
			} catch (err) {
				if (callback) callback(false);
				this.notifications.error('Failed to copy to clipboard');
			}
			$temp.remove();
		},
		debounce(func, wait) {
			let timeout;
			return function () {
				const context = this;
				const args = arguments;
				clearTimeout(timeout);
				timeout = setTimeout(function () {
					func.apply(context, args);
				}, wait);
			};
		},
		throttle(func, limit) {
			let inThrottle;
			return function () {
				const args = arguments;
				const context = this;
				if (!inThrottle) {
					func.apply(context, args);
					inThrottle = true;
					setTimeout(function () {
						inThrottle = false;
					}, limit);
				}
			};
		},
		formatNumber(num, decimals) {
			decimals = decimals || 0;
			return num.toFixed(decimals).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
		},
		timeAgo(date) {
			const now = new Date();
			const past = new Date(date);
			const seconds = Math.floor((now - past) / 1000);
			const intervals = {
				year: 31536000,
				month: 2592000,
				week: 604800,
				day: 86400,
				hour: 3600,
				minute: 60,
				second: 1,
			};
			for (const key in intervals) {
				const interval = Math.floor(seconds / intervals[key]);
				if (interval >= 1) {
					return (
						interval +
						' ' +
						key +
						(interval > 1 ? 's' : '') +
						' ago'
					);
				}
			}
			return 'just now';
		},
	};
	$(document).ready(function () {
		ShahiComponents.init();
	});
	window.ShahiNotify = ShahiComponents.notifications;
})(jQuery);
(function () {
	'use strict';
	const styles = `<style id="shahi-components-dynamic-styles">.shahi-notifications-container{position:fixed;top:32px;right:20px;z-index:999999;display:flex;flex-direction:column;gap:12px;max-width:400px;}.shahi-skeleton-item{display:flex;gap:16px;margin-bottom:16px;}@media(max-width:768px){.shahi-notifications-container{top:46px;right:10px;left:10px;max-width:none;}}</style>`;
	if (document.head) {
		document.head.insertAdjacentHTML('beforeend', styles);
	}
})();
